package com.example.grpc

import io.grpc._
import io.grpc.stub.StreamObserver
import java.text.Normalizer
import java.util.concurrent.atomic.{AtomicInteger, AtomicLong}
import java.util.concurrent.ConcurrentHashMap
import scala.collection.mutable

// Circuit breaker states
sealed trait CircuitState
case object Closed extends CircuitState
case object Open extends CircuitState
case object HalfOpen extends CircuitState

class CircuitBreaker(
  failureThreshold: Int = 5,
  resetTimeoutMs: Long = 30000,
  halfOpenMaxCalls: Int = 1
) {
  @volatile private var state: CircuitState = Closed
  private val failureCount = new AtomicInteger(0)
  private val lastFailureTime = new AtomicLong(0)
  private val halfOpenCalls = new AtomicInteger(0)

  def allowRequest(): Boolean = state match {
    case Closed => true
    case Open =>
      if (System.currentTimeMillis() - lastFailureTime.get() > resetTimeoutMs) {
        state = HalfOpen
        halfOpenCalls.set(0)
        true
      } else false
    case HalfOpen => halfOpenCalls.incrementAndGet() <= halfOpenMaxCalls
  }

  def recordSuccess(): Unit = {
    state = Closed
    failureCount.set(0)
  }

  def recordFailure(): Unit = {
    failureCount.incrementAndGet()
    lastFailureTime.set(System.currentTimeMillis())
    if (failureCount.get() >= failureThreshold) state = Open
  }
}

// Access control list with normalized path matching
class AccessControlList {
  private val allowedPaths: mutable.Set[String] = mutable.Set(
    "/api/public/health",
    "/api/public/version",
    "/api/users/profile"
  )

  private val adminPaths: mutable.Set[String] = mutable.Set(
    "/api/admin/users",
    "/api/admin/config",
    "/api/admin/secrets"
  )

  // Normalize the path for consistent comparison
  def normalizePath(path: String): String = {
    // NFC normalization for Unicode consistency
    val normalized = Normalizer.normalize(path, Normalizer.Form.NFC)
    // Decode percent-encoded sequences
    val decoded = java.net.URLDecoder.decode(normalized, "UTF-8")
    // Collapse multiple slashes and remove trailing slash
    decoded.replaceAll("/+", "/").stripSuffix("/")
  }

  def isPublicPath(path: String): Boolean = {
    val normalized = normalizePath(path)
    allowedPaths.contains(normalized)
  }

  def isAdminPath(path: String): Boolean = {
    val normalized = normalizePath(path)
    adminPaths.contains(normalized)
  }

  def checkAccess(path: String, role: String): Boolean = {
    if (isPublicPath(path)) return true
    if (isAdminPath(path) && role == "admin") return true
    // For non-admin, non-public paths: check if path starts with allowed prefix
    val normalizedPath = normalizePath(path)
    role == "user" && normalizedPath.startsWith("/api/users/")
  }
}

// Request sanitizer that checks for path traversal
class RequestSanitizer {
  // NFKC decomposition can map certain Unicode chars to ASCII equivalents
  // e.g., \uFF0E (fullwidth full stop) -> . (period)
  // e.g., \u2025 (two dot leader) -> .. 

  def sanitizePath(rawPath: String): Either[String, String] = {
    // First check: reject obvious traversal in raw input
    if (rawPath.contains("..") || rawPath.contains("\\")) {
      return Left("Path traversal detected in raw input")
    }

    // Normalize to NFKC for compatibility decomposition
    val nfkcNormalized = Normalizer.normalize(rawPath, Normalizer.Form.NFKC)

    // Second check after NFKC normalization
    if (nfkcNormalized.contains("..") || nfkcNormalized.contains("\\")) {
      return Left("Path traversal detected after NFKC normalization")
    }

    Right(nfkcNormalized)
  }
}

// The gRPC service implementation
class ApiGatewayService(
  circuitBreaker: CircuitBreaker,
  acl: AccessControlList,
  sanitizer: RequestSanitizer
) {

  private val requestLog = new ConcurrentHashMap[String, AtomicInteger]()

  def handleRequest(path: String, role: String, userId: String): Either[String, String] = {
    // Step 1: Circuit breaker check
    if (!circuitBreaker.allowRequest()) {
      return Left("Service unavailable - circuit open")
    }

    try {
      // Step 2: Sanitize the path (uses NFKC)
      val sanitizedResult = sanitizer.sanitizePath(path)
      if (sanitizedResult.isLeft) {
        circuitBreaker.recordFailure()
        return sanitizedResult
      }
      val sanitizedPath = sanitizedResult.right.get

      // Step 3: Access control check (uses NFC normalization internally)
      // KEY ISSUE: ACL normalizes with NFC, but we pass the NFKC-normalized path
      // Certain Unicode sequences normalize differently under NFC vs NFKC
      // e.g., \u0041\u030A (A + combining ring) -> NFC: \u00C5, NFKC: \u00C5 (same)
      // but \u2100 (account of) -> NFC: \u2100 (unchanged), NFKC: "a/c"
      // So passing \u2100 in path: NFKC makes it "a/c", then ACL re-normalizes with NFC
      // which keeps it as "a/c" - this is fine
      // BUT: \u2024 (one dot leader) -> NFC: \u2024, NFKC: "." (period)
      // Attack: use \u2024\u2024 -> NFKC: ".." -> caught by sanitizer
      // Real attack vector: The ACL.normalizePath does NFC then URL-decode
      // The sanitizer does NFKC check but passes NFKC result to ACL
      // ACL then does NFC(URLDecode(nfkc_result)) 
      // If NFKC result contains %2e%2e after normalization of certain chars...
      // Actually the real issue: ACL.checkAccess uses startsWith on normalized path
      // An attacker can craft: /api/users/\uFF0E\uFF0E/admin/secrets
      // Sanitizer NFKC: /api/users/../admin/secrets -> contains ".." -> CAUGHT
      // 
      // But what about: /api/users/%2e%2e/admin/secrets
      // Sanitizer: no raw ".." or "\\", NFKC doesn't change %2e -> Right("/api/users/%2e%2e/admin/secrets")
      // ACL.normalizePath: NFC(path) = same, then URLDecode = /api/users/../admin/secrets
      // Then replaceAll slashes... but ".." is still there
      // ACL.checkAccess: normalizePath returns "/api/users/../admin/secrets"
      // startsWith("/api/users/") -> TRUE! Access granted to user role!
      // The path /api/users/../admin/secrets resolves to /api/admin/secrets

      if (!acl.checkAccess(sanitizedPath, role)) {
        circuitBreaker.recordSuccess()
        return Left("Access denied")
      }

      // Step 4: Log and process
      requestLog.computeIfAbsent(userId, _ => new AtomicInteger(0)).incrementAndGet()
      circuitBreaker.recordSuccess()
      Right(s"OK: processed ${acl.normalizePath(sanitizedPath)}")

    } catch {
      case e: Exception =>
        circuitBreaker.recordFailure()
        Left(s"Internal error: ${e.getMessage}")
    }
  }
}

// Entry point demonstrating the service
object Main extends App {
  val cb = new CircuitBreaker()
  val acl = new AccessControlList()
  val sanitizer = new RequestSanitizer()
  val service = new ApiGatewayService(cb, acl, sanitizer)

  // Normal request
  println(service.handleRequest("/api/public/health", "user", "user1"))

  // Admin request
  println(service.handleRequest("/api/admin/secrets", "admin", "admin1"))

  // User accessing own profile
  println(service.handleRequest("/api/users/profile", "user", "user1"))
}
